88	template <typename T>
89	ACLSHMEM_DEVICE void aclshmemi_roce_team_sync(aclshmemx_team_t* team, __ubuf__ T* buf, uint32_t sync_id)
90	{
91	    int my_pe = aclshmemi_get_state()->team_pools[ACLSHMEM_TEAM_WORLD]->mype;
92	    int start = team->start;
93	    int stride = team->stride;
94	    int size = team->size;
95	    auto sync_pool = aclshmemi_get_team_sync_pool(team->team_idx);
96	    auto sync_counter = aclshmemi_get_team_sync_counter(team->team_idx);
97	
98	    int shift = 1;
99	    int my_pe_in_team = (my_pe - start) / stride;
100	    int32_t count = aclshmemi_load((__gm__ int32_t*)sync_counter) + 1;
101	    aclshmemi_store((__gm__ int32_t*)sync_counter, count);
102	    dcci_cacheline((__gm__ uint8_t*)sync_counter);
103	    while (shift < size) {
104	        int pre_pe_in_team = (my_pe_in_team - shift + size) % size;
105	        int next_pe_in_team = (my_pe_in_team + shift) % size;
106	        int next_pe = start + next_pe_in_team * stride;
107	
108	        aclshmemi_highlevel_signal_set(
109	            (__gm__ int32_t*)(sync_pool + my_pe_in_team), (__gm__ int32_t*)sync_counter, next_pe, buf, sync_id);
110	        aclshmemi_signal_wait_until_eq_for_barrier((__gm__ int32_t*)(sync_pool + pre_pe_in_team), count);
111	
112	        shift *= SHIFT_MULTIPLIER;
113	    }
114	}
