116	template <typename T>
117	ACLSHMEM_DEVICE void aclshmemi_roce_barrier(aclshmemx_team_t* team, __ubuf__ T* buf, uint32_t sync_id)
118	{
119	    __gm__ aclshmem_device_host_state_t* device_state = aclshmemi_get_state();
120	    int mype = device_state->team_pools[ACLSHMEM_TEAM_WORLD]->mype;
121	    int start = team->start;
122	    int stride = team->stride;
123	    int size = team->size;
124	
125	    if ((mype - start) % stride != 0) {
126	        return;
127	    }
128	
129	    AscendC::LocalTensor<uint32_t> ub_tensor_32;
130	    ub_tensor_32.address_.logicPos = static_cast<uint8_t>(AscendC::TPosition::VECOUT);
131	    ub_tensor_32.address_.bufferAddr = reinterpret_cast<uint64_t>(buf);
132	    ub_tensor_32.address_.dataLen = UB_ALIGN_SIZE;
133	    AscendC::LocalTensor<uint64_t> ub_tensor_64;
134	    ub_tensor_64.address_.logicPos = static_cast<uint8_t>(AscendC::TPosition::VECOUT);
135	    ub_tensor_64.address_.bufferAddr = reinterpret_cast<uint64_t>(buf) + UB_ALIGN_SIZE;
136	    ub_tensor_64.address_.dataLen = UB_ALIGN_SIZE;
137	
138	    for (int i = 0; i < size; i++) {
139	        int peer = start + i * stride;
140	        if (peer == mype) {
141	            continue;
142	        }
143	        aclshmemi_roce_quiet(peer, ub_tensor_64, ub_tensor_32, sync_id);
144	    }
145	
146	    aclshmemi_roce_team_sync(team, buf, sync_id);
147	}
