178	ACLSHMEM_DEVICE __gm__ void* aclshmem_roce_ptr(__gm__ void* ptr, int pe)
179	{
180	    // Get Global State
181	    __gm__ aclshmem_device_host_state_t* device_state = aclshmemi_get_state();
182	
183	    // Back to root address
184	    uint64_t offset = reinterpret_cast<uint64_t>(ptr) - reinterpret_cast<uint64_t>(device_state->heap_base);
185	    uint64_t remote_ptr = reinterpret_cast<uint64_t>(device_state->p2p_device_heap_base[pe]) + offset;
186	
187	    return reinterpret_cast<__gm__ void*>(remote_ptr);
188	}
